#include <iostream>

/*
   @pre nbr > 0
   @pos retorna el tamany de nbr
*/
int	ft_nbrlen(int nbr)
{
	int	i;

	i = 0;
	while (nbr-- > 0)
		i++;
	return (i);
}

/**
@pre n >= 0
@post retorna cert si n és un número entrepà, fals en cas contrari
*/
bool	is_sandwich(int n)
{
	int	esquerra;
	int	len;
	int	*pdreta;
	int	*pesquerra;

	esquerra = n % 10;
	len = ft_nbrlen(n);
	pesquerra = &esquerra;
	pdreta = pesquerra + len;
	while (len-- > 0)
	{
		if (pesquerra == pdreta)
			return (true);
		return (false);
	}
	return (false);
}
